do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='412f0440-2a53-55cf-874b-a815271eaf3f'; if prior is not null then if not prior @> '{"id":"412f0440-2a53-55cf-874b-a815271eaf3f","leaf_id":"9c3cb94f-4dac-5ae4-9198-fc7afbf193df","source_id":"1a14b9e0-9839-5040-af45-d2cc83ed6d1c","criterion_key":"official-q2-6","description":"내부 평가표 100점 기준, 실제 문항은 50점. f(3) 계산(10)","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('412f0440-2a53-55cf-874b-a815271eaf3f','9c3cb94f-4dac-5ae4-9198-fc7afbf193df','1a14b9e0-9839-5040-af45-d2cc83ed6d1c','official-q2-6','내부 평가표 100점 기준, 실제 문항은 50점. f(3) 계산(10)',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='d52cecf0-6a48-53c5-857b-21dda8bc570d'; if prior is not null then if not prior @> '{"id":"d52cecf0-6a48-53c5-857b-21dda8bc570d","leaf_id":"9c3cb94f-4dac-5ae4-9198-fc7afbf193df","source_id":"43fc60ec-ab72-53d5-96dd-e5a821049105","logical_id":"d52cecf0-6a48-53c5-857b-21dda8bc570d","version":1,"origin":"OFFICIAL","state":"DRAFT","body":"F(x)=∫[0,x]f는 짝함수다. 양의 축에서 F는 π까지 감소한 뒤 증가하고 2π에서만 다시 수평이다. eᵗ−cos t가 증가하므로 주기 반쪽씩 합쳐 적분하면 F(2π)>F(0). |F(x)−F(a)|가 전 구간 미분가능하려면 같은 높이인 모든 점에서 F′=0이어야 하므로 a=±π,±2π이다.\nP=(1,0), Q=((a²−1)/(1+a²),−2a/(1+a²)). R,S의 x좌표는 (a²−ak±√(1+a²−(a−k)²))/(1+a²), y는 a(x−1)+k이다. 평행선 거리 k/√(1+a²)에 두 현 길이를 각각 곱해 넓이의 하한과 상한을 얻는다. k로 나누면 2/(1+a²)와 2√(1+a²−(a−k)²)/(1+a²) 사이여서 극한은 2/(1+a²).\ng(1/4)=g′(1/4)=0,g″(1/4)=1. 연쇄법칙에 의해 f(0)=0,f′(0)=4. 최대 속력에서 g′(1)=1(부호는 h′와 f′로 결정), g″(1)=0. b=g(1)≥0이면 f′(b)=9/4, f″(b)=−2. f=x³+cx²+4x를 대입하면 3b+c=−1, 3b²+2cb+7/4=0. b=1/2,c=−5/2이고 f(3)=33/2."}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,logical_id,version,origin,state,body) values ('d52cecf0-6a48-53c5-857b-21dda8bc570d','9c3cb94f-4dac-5ae4-9198-fc7afbf193df','43fc60ec-ab72-53d5-96dd-e5a821049105','d52cecf0-6a48-53c5-857b-21dda8bc570d',1,'OFFICIAL','DRAFT','F(x)=∫[0,x]f는 짝함수다. 양의 축에서 F는 π까지 감소한 뒤 증가하고 2π에서만 다시 수평이다. eᵗ−cos t가 증가하므로 주기 반쪽씩 합쳐 적분하면 F(2π)>F(0). |F(x)−F(a)|가 전 구간 미분가능하려면 같은 높이인 모든 점에서 F′=0이어야 하므로 a=±π,±2π이다.
P=(1,0), Q=((a²−1)/(1+a²),−2a/(1+a²)). R,S의 x좌표는 (a²−ak±√(1+a²−(a−k)²))/(1+a²), y는 a(x−1)+k이다. 평행선 거리 k/√(1+a²)에 두 현 길이를 각각 곱해 넓이의 하한과 상한을 얻는다. k로 나누면 2/(1+a²)와 2√(1+a²−(a−k)²)/(1+a²) 사이여서 극한은 2/(1+a²).
g(1/4)=g′(1/4)=0,g″(1/4)=1. 연쇄법칙에 의해 f(0)=0,f′(0)=4. 최대 속력에서 g′(1)=1(부호는 h′와 f′로 결정), g″(1)=0. b=g(1)≥0이면 f′(b)=9/4, f″(b)=−2. f=x³+cx²+4x를 대입하면 3b+c=−1, 3b²+2cb+7/4=0. b=1/2,c=−5/2이고 f(3)=33/2.'); end if; end $row$;
